CREATE TABLE IF NOT EXISTS learning_updates (id VARCHAR(40) PRIMARY KEY, event_key VARCHAR(150) NOT NULL UNIQUE, course_id VARCHAR(40) NOT NULL, kind VARCHAR(30) NOT NULL, title VARCHAR(240) NOT NULL, body TEXT NOT NULL, link_path VARCHAR(240) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE INDEX IF NOT EXISTS learning_updates_course ON learning_updates(course_id,created_at);
CREATE TABLE IF NOT EXISTS learning_update_reads (update_id VARCHAR(40) NOT NULL, user_id VARCHAR(40) NOT NULL, read_at VARCHAR(30) NOT NULL, PRIMARY KEY(update_id,user_id), FOREIGN KEY(update_id) REFERENCES learning_updates(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS learning_reads_user ON learning_update_reads(user_id,update_id);
CREATE TABLE IF NOT EXISTS class_attendance_automation (class_id VARCHAR(40) PRIMARY KEY, mode VARCHAR(20) NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, started_at VARCHAR(30), started_by VARCHAR(40), closed_at VARCHAR(30), checked_at VARCHAR(30), needs_review INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(started_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS class_automatic_absences (class_id VARCHAR(40) NOT NULL, student_id VARCHAR(40) NOT NULL, attendance_id VARCHAR(40) NOT NULL, created_at VARCHAR(30) NOT NULL, PRIMARY KEY(class_id,student_id), FOREIGN KEY(class_id) REFERENCES classes(id), FOREIGN KEY(student_id) REFERENCES users(id), FOREIGN KEY(attendance_id) REFERENCES attendance(id));
